test('amounts such as 4.35 are kept to the cent and listed as sent', () => withApp(async call => {
  await call('POST', '/groups', trip)
  const amounts = [4.35, 0.29, 1.15, 8.2, 1000000, 0.01]
  for (const amount of amounts) {
    const r = await call('POST', '/groups/trip/expenses', { description: `Item ${amount}`, payer: 'Ann', amount, split: ['Ann'] })
    assert.equal(r.status, 201)
    assert.equal(r.body.amount, amount)
  }
  const listed = await call('GET', '/groups/trip/expenses')
  assert.deepEqual(listed.body.expenses.map(e => e.amount), amounts)
}))

test('an uneven split gives the first people in split one cent more', () => withApp(async call => {
  await call('POST', '/groups', trip)
  const r = await call('POST', '/groups/trip/expenses', { description: 'Dinner', payer: 'Ann', amount: 10 })
  assert.deepEqual(r.body.shares, { Ann: 3.34, Ben: 3.33, Cara: 3.33 })
  assert.deepEqual(Object.keys(r.body.shares), ['Ann', 'Ben', 'Cara'])
  assert.deepEqual((await call('GET', '/groups/trip/balances')).body, { balances: { Ann: 6.66, Ben: -3.33, Cara: -3.33 } })
  const gum = await call('POST', '/groups/trip/expenses', { description: 'Gum', payer: 'Ben', amount: 0.01, split: ['Cara', 'Ann'] })
  assert.deepEqual(gum.body.shares, { Cara: 0.01, Ann: 0 })
  assert.deepEqual(Object.keys(gum.body.shares), ['Cara', 'Ann'])
}))

